    process.argv.slice(2).every((arg) => arg === '--check'),
    'Usage: node scripts/build-api-index.cjs [--check]',
  );
  const root = path.resolve(__dirname, '..');
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'ctt-api-index-'));
