    execFileSync(
      process.execPath,
      [path.join(__dirname, 'api-clarity-census.cjs'), temporary],
      { cwd: root, stdio: 'pipe' },
    );
    const census = JSON.parse(
      fs.readFileSync(path.join(temporary, 'public-api-census.json'), 'utf8'),
    );
